SELECT id, task_id, chunk_id, code, COALESCE(display_title,'') AS display_title, level, title, COALESCE(summary,'') AS summary, COALESCE(explain,'') AS explain, COALESCE(connection,'') AS connection, COALESCE(examples,'') AS examples, examples_edited, COALESCE(orig_title,'') AS orig_title, seq, COALESCE(item_codes,'') AS item_codes, COALESCE(point_codes,'') AS point_codes, status, COALESCE(confidence,'') AS confidence, COALESCE(dropped_codes,'') AS dropped_codes, COALESCE(reason,'') AS reason, COALESCE((SELECT subject_id FROM textbook_import_task WHERE id = textbook_import_draft.task_id),1) AS subject_id FROM textbook_import_draft WHERE id = CAST(:id AS INTEGER)
